// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }
    function testFuzz_property(uint256 time, uint256 blockSeed, address actor) public {
        vm.assume(actor != address(c) && actor != address(this));
        time = bound(time, 1, type(uint48).max);
        // pick a block height; the fuzzer can hit multiples of 15 (e.g. 15, 30, ...)
        uint256 height = bound(blockSeed, 15, 30000);
        vm.roll(height);
        vm.warp(time);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        // General rule: a successful call on a payout block drains c's balance to 0.
        assertTrue(!ok || height % 15 != 0 || address(c).balance == 0);
    }
}
